// Entry for the vendored 3D library (registry/build-vendor-three.mjs bundles it). Only the classes the puppet
// scene uses are exported, so the bundle leaves out everything else. No loaders, so no model or texture can load.
export {
  ACESFilmicToneMapping,
  BoxGeometry,
  BufferGeometry,
  CapsuleGeometry,
  CircleGeometry,
  Color,
  CylinderGeometry,
  DirectionalLight,
  Float32BufferAttribute,
  Fog,
  Group,
  HemisphereLight,
  LatheGeometry,
  MathUtils,
  Mesh,
  MeshBasicMaterial,
  MeshPhysicalMaterial,
  PCFSoftShadowMap,
  PerspectiveCamera,
  PlaneGeometry,
  Plane,
  Points,
  PointsMaterial,
  Ray,
  SRGBColorSpace,
  Scene,
  SphereGeometry,
  Vector2,
  Vector3,
  WebGLRenderer,
} from "three";
